'QZ_Step_Install' => '1. Install QZ Tray on this computer — download it free from qz.io, then start it and leave it running (it sits in the system tray on Windows or the menu bar on macOS).',
'QZ_Step_Connect' => '2. Connect your label printer by USB and check that it is installed in the operating system (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
