'Ord_Guide_MarkPaid_Note' => 'The Payment Status shown here keeps recording the checkout choice and stays as it is. The sale is the accounting record, and it is what feeds your payment and profit reports. Use Show Payments on the sale to review or edit what you entered.',
'Ord_Guide_Notes_Title' => 'Good to know',
'Ord_Guide_Note_Warehouse' => 'The warehouse you pick when confirming decides where the stock is taken from. Warehouses that cannot cover the whole order are marked Out of Stock in that list.',
'Ord_Guide_Note_Preorder' => 'Pre-order items skip the stock check, so an order containing them can be confirmed even when the quantity is not on hand yet.',
'Ord_Guide_Note_Flagged' => 'A Flagged tag means the order tripped a fraud check at checkout. Hover the tag to see the reason and review the order before confirming it.',
'Ord_Guide_Note_Cancel' => 'Cancelling is only possible while the order is still pending. Once it is confirmed, reverse it through the sale or a customer return instead.',


