// Variants guide drawer (product form).
'Guide' => 'Guide',
'Variants_Guide' => 'Variants guide',
'VG_Intro' => 'A variable product is sold as several variants. Build them from options (recommended) or as a simple list of names. Every variant has its own code, prices, image and stock.',
'VG_Options_Title' => 'Options mode (Color, Size...)',
'VG_Opt_Step1' => 'Keep the switch in the card header on "Options".',
'VG_Opt_Step2' => 'Type an option name such as Color or Size, or pick one of the suggestions.',
'VG_Opt_Step3' => 'Type a value (for example Red) and press Enter. Repeat for each value; a comma also separates values. Click the x on a value to remove it.',
'VG_Opt_Step4' => 'Click "Add option" for a second or third option (3 options maximum).',
'VG_Opt_Step5' => 'Click "Generate variants". One row is created per combination and its name is built automatically, for example "Red / S".',
'VG_Opt_Step6' => 'Enter cost and price on each row, or type a value in "Apply to all" and click Cost or Price to copy it into every row.',
'VG_Opt_Step7' => 'Codes are generated for you. Type your own or click the refresh icon to generate another one.',
'VG_Opt_Step8' => 'Optional: tick "Color swatches" on an option and pick a color for each value; the store shows it as a colored dot.',
'VG_Rows_Title' => 'Variant rows',
'VG_Rows_Text' => 'Each row has an image, code, barcode, cost, price, wholesale price and minimum selling price. When creating a product you can also enter the opening stock per warehouse for every variant. An "Incomplete" tag means the row is missing a value for one option.',
'VG_List_Title' => 'Simple list mode',
'VG_List_Text' => 'Type a variant name and press Enter (or click Add) to append a row, then fill in its code and prices. This is the classic behaviour and stays available for existing products.',
'VG_Edit_Title' => 'Editing later',
'VG_Edit_1' => 'Add a value and click "Generate variants": only the missing combinations are added. Existing rows keep their codes, prices and history.',
'VG_Edit_2' => 'Removing a value or an option removes the rows that use it. Rows already saved are deleted when you save the product, after a confirmation.',
'VG_Edit_3' => 'A variant that still has stock cannot be removed. Adjust or transfer its stock first.',
'VG_Edit_4' => 'Switching to "Simple list" keeps the rows and their names but drops the option definitions.',
'VG_Store_Title' => 'On the online store',
'VG_Store_Text' => 'Customers pick one value per option, for example Color then Size. Combinations that do not exist are disabled and out-of-stock ones are struck through. The chosen variant is what goes to the cart.',
