'Upd_Note_Code_Changes_Lost' => 'Note 1: If you have made any changes in the code manually then your changes will be lost.',
'Upd_Manual_Steps_Intro' => 'Please follow these steps to update your application',
'Upd_Note_Permission_Only' => 'Note 2: only an admin or a user who has the permission "{perm}" can upgrade the system',
'Upd_Manual_Step_Backup_Db' => 'Take a backup of your database. Go to {backup}, click Generate Backup — you will find it in {path} — or export your database from PhpMyAdmin and save it to your PC.',
'Upd_Manual_Step_Backup_Files' => 'Take a backup of your files before updating.',
'Upd_Manual_Step_Download' => 'Download the latest version from your CodeCanyon account and extract it.',
'Upd_Manual_Step_Remove' => 'Remove the previous files, {except}:',
'Upd_Except' => 'except',
'Upd_File_Label' => 'file: {name}',
'Upd_Folder_Label' => 'folder: {name}',
'Upd_Manual_Step_Reupload' => 'Re-upload the files and folders from the new update, {except} the same three paths above.',
'Upd_Manual_Step_Visit' => 'Visit {url} to update your database.',
'Upd_Manual_Step_Clear_Cache' => 'Hard-clear your browser cache.',
'Upd_Manual_Step_Done' => 'You are done! Enjoy the updated application.',
'Upd_Note_Blank_Pages' => 'Note: If any pages are not loading or blank, make sure you cleared your browser cache.',
'Upd_Guide_Before_Title' => '1. Before you update',
'Upd_Guide_Before_Download' => 'Download the {package} of the application from your CodeCanyon account ({path}). Do not extract it — the updater needs the ZIP exactly as downloaded.',
'Upd_Latest_Full_Zip' => 'latest full ZIP package',
'Upd_Guide_Before_Admin' => 'Make sure you are logged in as an administrator who has the {perm} permission. Nobody else can see or run the updater.',
'Upd_Guide_Before_Quiet' => 'Pick a quiet moment: during the update the application switches to maintenance mode for a short time and other users are locked out.',
'Upd_Guide_Before_No_Manual' => 'You do {not} need to back up manually, extract files, run commands, edit configuration files, or touch the database — the updater does all of that automatically. (An extra manual backup never hurts, of course.)',
'Upd_Not' => 'not',
'Upd_Guide_Code_Overwritten' => 'If you have modified the application code manually, your changes will be overwritten by the update. Your data, uploads, settings and .env are always preserved.',
'Upd_Guide_Running_Title' => '2. Running the update',
'Upd_Guide_Run_Open' => 'Open {path} (this page) and stay on the {tab} tab.',
'Upd_Guide_Run_Upload' => '{upload}: click or drag the downloaded package into the upload box. Large files are uploaded in small chunks, so this also works on shared hosting with low upload limits. A checksum guards against corrupted or incomplete uploads.',
'Upd_Upload_The_Zip' => 'Upload the ZIP',
'Upd_Guide_Run_Validation' => '{auto} after the upload (you can re-run it with the {button} button). The system checks: ZIP integrity, package structure and completeness, version compatibility (downgrades are refused), required PHP version and extensions, file permissions, free disk space, database connection, configuration, and that no other update is running.',
'Upd_Validation_Runs_Automatically' => 'Validation runs automatically',
'Upd_Guide_Run_Review' => 'Review the {panel} panel. The {button} button only appears when every critical check passes. If a check fails, the message tells you exactly what to fix.',
'Upd_Guide_Run_Click' => 'Click {button} and confirm. Then simply {keep} and watch the progress rail. The system performs, in order:',
'Upd_Keep_Page_Open' => 'keep this page open',
'Upd_Guide_Phase_Backup' => '{label} — a full database dump, a ZIP of every application file the update can change, and a copy of {env} are created and {verified}. Your uploads ({images}) and {storage} are never touched by an update, so they are not archived. If a backup cannot be created, the update stops here and nothing is changed.',
'Upd_Verified' => 'verified',
'Upd_Guide_Phase_Prepare' => '{label} — the new version is extracted into a staging area and validated again. The live application is still untouched.',
'Upd_Guide_Phase_Maintenance' => '{label} — maintenance mode is enabled; visitors see a friendly "We\'ll be right back" screen.',
'Upd_Guide_Phase_Files' => '{label} — the new files are switched in near-instantly; the old files are kept aside for rollback. Protected paths ({env}, {storage}, {images}) are never replaced.',
'Upd_Guide_Phase_Database' => '{label} — migrations run, then permissions, translations and templates are refreshed.',
'Upd_Guide_Phase_Cache' => '{label} — all caches are cleared and rebuilt.',
'Upd_Guide_Phase_Verify' => '{label} — health checks confirm the new version boots, the database works, all migrations ran, and configuration is valid.',
'Upd_Guide_Phase_Done' => '{label} — maintenance mode is lifted and temporary files are cleaned up.',
'Upd_Guide_Run_Success' => 'When you see {success}, click {reload} and hard-refresh your browser ({keys}) so the new admin panel assets load.',
'Upd_Update_Successful_Short' => 'Update successful',
'Upd_Guide_No_Internet' => 'No internet connection is needed during the update — everything comes from the uploaded ZIP. Losing your connection or closing the browser does NOT break the update: the server remembers exactly where it stopped.',
'Upd_Guide_Wrong_Title' => '3. If something goes wrong',
'Upd_Guide_Wrong_Rollback' => '{label} — if anything fails after files started changing (extraction error, migration failure, failed health check, disk full, …), the system automatically restores the previous files and the database from the verified backup, lifts maintenance mode, and reports {message}. You end up exactly where you started.',
'Upd_Automatic_Rollback' => 'Automatic rollback',
'Upd_Failed_Previous_Restored' => 'Update failed — previous version restored',
'Upd_Guide_Wrong_Interrupted' => '{label} (server restart, timeout, closed browser, power loss) — when you reopen this page, a red banner offers two safe choices: {resume} (resumes from the exact step where it stopped) or {rollback} (restores the previous version from the backup).',
'Upd_Interrupted_Update' => 'Interrupted update',
'Upd_Guide_Wrong_Unreachable' => '{label} — use the standalone {console} at {path}. It works even while the site is in maintenance mode or the admin panel assets are broken, and offers the same Continue / Roll back actions. There is also a discreet "Administrator access" link at the bottom of the maintenance screen.',
'Upd_Admin_Unreachable' => 'Admin panel unreachable',
'Upd_Recovery_Console' => 'recovery console',
'Upd_Guide_Wrong_Locked_Out' => '{label} — while an update is running, this page shows a {link}. Save it if you need to get back in (for example after your session expired); it lets you through the maintenance screen so you can log in again.',
'Upd_Locked_Out_Maintenance' => 'Locked out by maintenance mode',
'Upd_Bypass_Link' => 'bypass link',
'Upd_Guide_Wrong_Concurrent' => '{label} — they will see {message} Only one update can ever run at a time.',
'Upd_Another_Admin_Updating' => 'Another admin tries to update at the same time',
'Upd_Guide_Backups_Title' => '4. Backups & restore',
'Upd_Guide_Backups_Created' => 'Every update creates a backup {before} touching anything: all application files the update can replace, a copy of {env}, and a full database dump. Uploads and {storage} are never modified by an update and are therefore not part of it — keep your own backups of those. Backups live in {path} and are never accessible from the web.',
'Upd_Before' => 'before',
'Upd_Guide_Backups_Panel' => 'The {panel} panel on the {tab} tab lists them with date, version and size. From there you can {restore} any complete backup (files + database — a safety copy of the current database is taken first) or {delete} old ones.',
'Upd_Restore_Verb' => 'restore',
'Upd_Delete_Verb' => 'delete',
'Upd_Guide_Backups_Retention' => 'Use {keep} to choose how many backups are retained; older ones are removed automatically after each successful update. The only remaining complete backup can never be deleted — you always keep a way back.',
'Upd_Guide_Manual_Title' => '5. Manual update (fallback method)',
'Upd_Guide_Manual_Text' => 'If you prefer updating by hand, or the uploader cannot be used on your server, follow the step-by-step instructions on the {tab} tab of this page.',
'Upd_Guide_Clear_Cache_First' => 'If pages look broken or blank after any update, clear your browser cache first — it is almost always the cause.',
'Upd_Restore_Backup_Confirm' => 'Restore this backup? Current files and the current database will be replaced by the backup. A safety copy of the current database is taken first. (v{version} — {date})',
'Woo_Guide_Lead' => 'How a WooCommerce shop keeps itself in step with the ERP. The cron lines below are built for this server, so they can be copied straight onto it.',
'Woo_Guide_Ways_Note' => 'Unlike Shopify, WooCommerce sends nothing to the ERP by itself — there is no webhook receiver here, so everything coming {in} arrives on the schedule. Only stock going {out} can be immediate.',
'Woo_In' => 'in',
'Woo_Out' => 'out',
'Woo_Guide_Both_Ways_Title' => 'Both ways need this first',
'Woo_Api_Keys' => 'API keys',
'Woo_Guide_Api_Keys_Text' => '{path}, permission {perm}. Copy the consumer key and secret into the {settings} tab, along with the store URL — your site\'s address with no trailing slash, e.g. {example}.',
'Woo_Credentials_Saved' => 'credentials saved',
'Woo_Not_Configured_Yet' => 'not configured yet',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress application password (optional)',
'Woo_Guide_Wp_App_Password_Text' => 'Only used for product images. The WooCommerce API moves products, stock, categories, brands, customers and orders; the WordPress API is what searches the Media Library and uploads an image that is not there yet.',
'Woo_Guide_Wp_App_Password_Note' => 'Use a WordPress user who can manage media, and create the password under {path}. Leave both fields blank and everything still syncs — only image attachment is skipped.',
'Woo_Guide_Pick_Way_Title' => 'Then pick how it keeps in step',
'Woo_Right_Away' => 'Right away',
'Woo_Stock_Live' => 'stock live',
'Woo_Stock_Not_Live' => 'stock not live',
'Woo_Guide_Realtime_Lead' => 'One direction only: stock and products leaving the ERP. Orders and product edits made in WooCommerce still arrive on the schedule — see the other tab.',
'Woo_Push_Stock_On_Change' => 'Push stock the moment it changes',
'Woo_Setting_People_Miss' => 'This is the setting people miss',
'Woo_Guide_Pos_Sale_Not_Reach' => 'A POS sale {not} reach WooCommerce by itself. Left off, the shop only finds out on the next stock sync — an hour, by default — and in that window it can sell a unit you have already sold at the till.',
'Woo_Does_Not' => 'does not',
'Woo_Guide_Tick_Instant' => 'Tick {option} on the {settings} tab. That is the whole setup — no worker, no cron. Every sale, return, adjustment, transfer and received purchase then sends a push of just those products, right after the sale is saved, and a twenty-line sale costs one push, not twenty. The till never waits for it.',
'Woo_Currently' => 'Currently:',
'Woo_Instant_On_Text' => 'on — stock pushed on change',
'Woo_Instant_Off_Text' => 'off — stock on the schedule only',
'Woo_Guide_Instant_Note' => 'Only products already linked to WooCommerce are pushed — one that has never been synced has nothing in the shop to correct. Variable products go through their parent, and a combo is re-pushed when any of its components move. Bulk operations (deleting a product, resetting a warehouse) write stock without firing an event, which is one reason to keep the hourly stock sync as well.',
'Woo_Push_Products_On_Save' => 'Push products the moment they are saved',
'Woo_Guide_Tick_Auto_Products' => 'Tick {option} on the {settings} tab and a product created, edited or duplicated in Stocky is sent to WooCommerce right after it is saved — details, price, variants and images, then its stock. A new product is created in the shop at once instead of waiting for the nightly products sync.',
'Woo_On' => 'on',
'Woo_Off' => 'off',
'Woo_Guide_Bulk_Imports_Note' => 'Bulk imports are not pushed one by one — run a products sync after an import. Sync categories and brands first, so a pushed product lands in the right category.',
'Woo_Nothing_Else_To_Install' => 'Nothing else to install',
'Woo_Guide_Same_Process' => 'No queue worker, no cron entry. The push runs in the same process that served the sale, {after} the response has gone back, so the till is never waiting on WooCommerce. Pushes never overlap: changes made while one is running wait for it and go out right after.',
'Woo_After' => 'after',
'Woo_Guide_Shop_Stops_Answering' => 'A shop that stops answering is given up on after eight seconds, and pushes pause for five minutes so that every sale does not wait on it again; the changes that came in meanwhile go out with the first push after the pause, and the hourly stock sync catches up regardless. Each pause is recorded in the Logs tab.',
'Woo_Guide_Artisan_Exception' => 'One exception: a stock change made by an artisan command has no response to come after, so it is queued on {queue} instead. To have those go out promptly too, drain that queue:',
'Woo_Cron_Line_Copied' => 'Cron line copied',
'Woo_Command_Copied' => 'Command copied',
'Woo_Guide_Not_Woo_Queue' => 'Deliberately not the {queue} queue: that one carries the hours-long catalogue batches, and an instant push queued behind one would not be instant.',
'Woo_On_A_Schedule' => 'On a schedule',
'Woo_Guide_Scheduled_Lead' => 'Everything is re-checked every so often, both ways. This is how orders reach the ERP, how a catalogue is published, and what repairs anything the fast path missed. Each job gets its own cron entry, so you run only what you want.',
'Woo_Guide_Sync_Drains_Queue' => '{command} drains its own queue while it runs, so these lines need no separate worker. On Windows, use Task Scheduler with program {program} and the same arguments, started in {path}.',
'Woo_Or_No_Cron' => 'Or no cron at all',
'Woo_Guide_No_Cron_Text' => 'Every tab here syncs on demand, and a manual sync drains its own batches while the page is open — so a small shop can run without any cron entry at all. What you lose is everything happening while nobody is looking: orders only arrive when someone presses the button.',
'Woo_Commands_Worth_Knowing' => 'Commands worth knowing',
'Woo_Worth_Knowing' => 'Worth knowing',
'Woo_Guide_Changing_Url_Clears' => 'Changing the store URL or the API keys clears every mapping — products, categories, brands and customers all sync again to the new store.',
'Woo_Guide_Keep_Skus' => 'Keep SKUs consistent between Stocky and WooCommerce: that is what stops duplicates and what makes relinking safe.',
'Woo_Guide_Stock_Total' => 'Stock published to Woo is the {total}, not one warehouse\'s figure.',
'Woo_Total_Across_Warehouses' => 'total across every warehouse',
'Woo_Guide_Full_Reference' => 'The full reference — every scope, how the queue behaves, and a troubleshooting list — is in {file}.',
'Woo_Way_Covers' => 'Covers',
'Woo_Way_Covers_Realtime' => 'Stock leaving the ERP only — a POS sale, a return, an adjustment, a received purchase',
'Woo_Way_Covers_Scheduled' => 'Everything, both ways: orders and product changes in, catalogue and stock out',
'Woo_Way_Speed' => 'Speed',
'Woo_Way_Seconds' => 'Seconds',
'Woo_Way_Speed_Scheduled' => 'Whatever you put in the cron entry (hourly stock, orders every 15 min)',
'Woo_Way_Needs' => 'Needs',
'Woo_Way_Needs_Realtime' => 'Nothing — just the setting',
'Woo_Way_Needs_Scheduled' => 'A cron entry per job — or nothing, if you sync by hand',
'Woo_Way_Switched_On_At' => 'Switched on at',
'Woo_Way_Cron_Entries_Below' => 'The cron entries below',
'Woo_Cron_Orders' => 'Orders every 15 minutes — only those changed since the last run.',
'Woo_Cron_Products_Pull' => 'Product changes from the shop, nightly at 03:00.',
'Woo_Cron_Customers' => 'Customers, nightly at 03:30.',
'Woo_Cron_Stock' => 'Stock every hour — the safety net under instant push, and the only stock sync without it.',
'Woo_Cron_Products_Push' => 'Products not yet linked, nightly at 02:00. Existing products are not rewritten.',
'Woo_Cmd_Stock' => 'Push stock for every linked product now.',
'Woo_Cmd_Products_Unsynced' => 'Publish products that have no WooCommerce id yet.',
'Woo_Cmd_Orders' => 'Import orders changed since the last run.',
'Woo_Cmd_Orders_Full' => 'Rescan every order instead of only recent changes.',
'Woo_Cmd_Pull' => 'Everything inbound at once: products, orders, customers.',
'Woo_Guide_Page_Title' => 'WooCommerce guide',
'Woo_Guide_Page_Subtitle' => 'Connecting the shop, what runs by itself, and the cron entries for this server',
'Woo_Settings_Button' => 'WooCommerce settings',
'Woo_No_Shop_Connected' => 'No shop is connected yet',
'Woo_No_Shop_Connected_Desc' => 'Everything below still applies — enter the store URL and API keys on the WooCommerce settings page, then come back.',
'Woo_Wp_Username' => 'WordPress username',
'Woo_Wp_App_Password' => 'WordPress application password',
'Woo_Settings_Instant_Hint' => 'A sale, return or adjustment sends a stock push for just those products the instant it is saved, so the shop is right within seconds instead of at the next hourly stock sync. Nothing else to install — the push runs after the sale has been answered, so the till never waits for WooCommerce. More on the {guide} tab.',
'Woo_Settings_Instant_Off_Alert' => 'Leave it off and a POS sale reaches WooCommerce only on the next stock sync — up to an hour later.',
'Woo_Settings_Auto_Products_Hint' => 'A product created, edited or duplicated in Stocky is sent to WooCommerce right after it is saved — details, price, variants, images, then its stock — instead of waiting for a products sync. Bulk imports are not pushed; run a products sync after an import.',
'Woo_Sync_Tuning' => 'Sync tuning',
'Woo_Sync_Tuning_Intro' => 'The defaults suit most stores. Change these only if sync is slow or times out on your hosting. Every value is capped to a safe range, and clearing a field restores its default.',
'Woo_Setting_This_Up' => 'Setting this up',
'Woo_Setting_This_Up_Text' => 'Getting the API keys, what the WordPress application password is for, the cron entries for scheduled syncs, and how to make stock reach the shop the moment it changes — all of it, with this server\'s own cron lines ready to copy, lives on the Guide tab. One copy, so it cannot drift from what the module actually does.',
