'Telegram_Bot_Token_Help' => 'Create a bot with {bot} in Telegram and paste its token here.',
'Telegram_Chat_ID' => 'Chat ID',
'Telegram_Chat_ID_Placeholder' => 'e.g. {example} for a group, or a user id',
'Telegram_Chat_ID_Help' => 'Add the bot to your group or channel, then get the chat id — for example by forwarding a message to {bot}, or from the bot\'s {api} API response.',
