'Telegram_G_Step1_Title' => 'Create the bot',
'Telegram_G_Step1_Body' => 'In Telegram, open a chat with {botfather}, send {cmd}, and pick a name and a username for the bot. BotFather replies with a {token} such as {example} — copy it.',
'Telegram_G_Bot_Token_Inline' => 'bot token',
