'Telegram_G_GetUpdates_Intro' => 'For a group or channel, open this address in a browser with your own token in it, and refresh it after posting:',
'Telegram_G_Chat_Id_Note' => 'Look for {json}. A group or channel ID is negative, e.g. {example} — copy all of it, minus sign included.',
'Telegram_G_Step3_Title' => 'Connect it here',
'Telegram_G_Step3_Body' => 'On the {settings} tab paste the bot token and the chat ID, choose {all} or only the ones you want {events}, switch on {enable} and save. Then press {test}.',
'Telegram_G_State_Enabled' => 'enabled',
'Telegram_G_State_Off' => 'saved, but switched off',
'Telegram_G_State_Not_Configured' => 'not configured yet',
'Telegram_G_Chat_Label' => 'chat {id}',
'Telegram_G_How_Sent' => 'How messages are sent',
'Telegram_G_A_Title' => 'Right away — nothing to install',
'Telegram_G_A_Body' => 'A sale, purchase, payment or expense saved in Stocky — at the POS or in the admin — is sent to Telegram {after} it has been saved, in the same request. No cron entry, no queue worker, and the cashier never waits for Telegram: the sale has already been answered when the message goes out.',
'Telegram_G_Right_After' => 'right after',
'Telegram_G_B_Title' => 'The cron entry — for retries and background events',
'Telegram_G_B_Body' => 'Two kinds of message wait on Telegram\'s own queue instead: a send that failed (Telegram unreachable for a moment), which is retried up to three more times over the next few minutes; and events raised outside the admin — orders imported from WooCommerce or Shopify, artisan commands. This cron entry sends them, and nothing else:',
'Telegram_G_Cron_Note' => 'Every minute is right: a run with nothing waiting exits at once. On cPanel this goes in {cronJobs} — use the full path to PHP 8.2+ if {php} is older. On Windows, use Task Scheduler with program {program}, arguments {args}, started in {path}.',
'Telegram_G_Waiting' => '{n} waiting to be sent',
'Telegram_G_Nothing_Waiting' => 'nothing waiting',
'Telegram_G_Gave_Up' => '{n} gave up after retries',
'Telegram_G_Growing_Note' => '— if this number keeps growing, the cron entry is not running.',
'Telegram_G_Without_Cron' => 'Without the cron entry, everything saved in Stocky still arrives instantly; you only lose the retries and the imported orders.',
'Telegram_G_Everything_Else' => 'Everything else',
'Telegram_G_Platform_Delivers' => 'Messages for events raised in the background are delivered by the platform — there is nothing to set up.',
'Telegram_G_Not_Arrive' => 'If it does not arrive',
'Telegram_G_Err_401' => '{error} — the bot token is wrong. Paste it again from BotFather.',
'Telegram_G_Err_400' => '{error} — wrong chat ID, or the bot is not in the group. For a personal chat, message the bot first.',
'Telegram_G_Err_403' => '{error} — add the bot back to the group, or as an admin of the channel.',
'Telegram_G_Test_Works' => '{label} — check the event is ticked (or {all} is chosen) and the switch is on.',
'Telegram_G_Test_Works_Label' => 'The test works but sales do not',
'Telegram_G_Imported_Missing' => '{label} — the cron entry above is not running.',
