'Jumia_Hero_Title' => 'Jumia marketplace sync',
'Jumia_Hero_Desc' => 'Push prices and stock to your Jumia Seller Center listings and import marketplace orders as sales.',
'Jumia_Api_Url_Label' => 'API URL (your country\'s Seller Center endpoint)',
'Jumia_Account_Email' => 'Account email (User ID)',
'Jumia_Api_Key' => 'API key',
'Jumia_Prices_Stock' => 'Prices & Stock',
'Jumia_Push_Prices_Stock_Title' => 'Push prices & stock to Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Sends the current price and quantity for every product (and variant) that has a SKU matching the Jumia listing\'s {sku}. Updates are submitted as Seller Center feeds and applied asynchronously — the feed ID is recorded in the Logs tab, and per-item rejections appear in Seller Center\'s feed status screen.',
'Jumia_Push_Prices_Stock' => 'Push prices & stock',
'Jumia_Pull_Orders_Desc' => 'Imports marketplace orders as sales (references like {ref}), matched to your products by Seller SKU. Already-imported and cancelled orders are skipped, so pulling regularly is safe. Payments are marked paid only for delivered orders (Jumia is COD-dominant).',
'Jumia_Guide_1' => 'In Jumia {sellerCenter}, open {menu} and generate an API key.',
'Jumia_Guide_2' => 'Enter your country\'s API URL (e.g. {ng} for Nigeria, {ke} for Kenya, {eg} for Egypt), your Seller Center account email, and the key — then run {test}.',
'Jumia_Guide_3' => 'Make sure each Jumia listing\'s {sku} equals the Stocky product code — that is the identity used for both stock pushes and order matching.',
'Jumia_Guide_4' => 'Push prices & stock after inventory changes; pull orders regularly (Jumia has no webhooks in this API).',
'Jumia_Guide_5' => 'Creating new listings stays in Seller Center — Jumia requires category-specific attributes and image review that only their portal handles well.',
'Mailchimp_Hero_Title' => 'Mailchimp audience sync',
'Mailchimp_Hero_Desc' => 'Keep a Mailchimp audience filled with your customers, so you can run email campaigns on your real customer base.',
'Mailchimp_Account_Audience' => 'Account & audience',
'Mailchimp_Api_Key_Ph' => 'e.g. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} members)',
'Mailchimp_Load_Audiences_Ph' => 'Load audiences to pick one',
'Mailchimp_Load_Audiences' => 'Load audiences',
'Mailchimp_Double_Optin_Label' => 'Double opt-in — new members get a confirmation email before joining',
'Mailchimp_Double_Optin_Hint' => '(recommended for GDPR)',
'Mailchimp_Auto_Sync_Customers' => 'Auto-sync new customers as they are created',
'Mailchimp_With_Email' => 'With an email',
'Mailchimp_Push_Desc' => 'Upserts every customer that has an email address into the selected audience (name and phone included). Existing members keep their subscription status — nobody who unsubscribed is re-subscribed. Customers without an email are left out.',
'Mailchimp_Double_Optin_Off_Title' => 'Double opt-in is off',
'Mailchimp_Double_Optin_Off_Desc' => 'New members will be added as subscribed without a confirmation email. Only do this for customers who already agreed to receive marketing.',
'Mailchimp_Guide_1' => 'In Mailchimp, open {menu} and create a key (it ends in {suffix} — that suffix is your datacenter).',
'Mailchimp_Guide_2' => 'Paste the key here, save, then click {load} and pick the audience to fill.',
'Mailchimp_Guide_3' => 'Leave {doubleOptIn} on unless your customers have already consented to marketing emails.',
'Mailchimp_Double_Optin_Term' => 'double opt-in',
'Mailchimp_Guide_4' => 'Run {push} for the initial fill; turn on {autoSync} so new customers join automatically.',
'Mailchimp_Auto_Sync_Term' => 'auto-sync',
'Mailchimp_Consent_Title' => 'Consent matters',
'Mailchimp_Consent_Desc' => 'Emailing people who never agreed to marketing can violate GDPR/CAN-SPAM and get your Mailchimp account suspended. Double opt-in shifts the confirmation to Mailchimp — the safe default.',
'Mailchimp_No_Audiences' => 'No audiences found on this account.',
