'Shopify_Subscribed' => 'Subscribed',
'Shopify_Could_Not_Read_Hooks' => 'Could not read this shop\'s webhooks',
'Shopify_Hooks_Partial' => '{created} created, {failed} failed — see the logs',
'Shopify_Subs_Created' => '{n} subscription(s) created',
'Shopify_Subs_Created_Removed' => '{n} subscription(s) created, {removed} removed',
'Shopify_Already_Subscribed' => 'Already subscribed to everything this store needs',
'Shopify_Could_Not_Register' => 'Could not register webhooks',
'Shopify_Sub_Removed' => 'Subscription removed',
'Shopify_Could_Not_Remove_Sub' => 'Could not remove that subscription',
'Shopify_Could_Not_Load_Store' => 'Could not load this store',
'Shopify_G_Lead_Store' => 'What this shop needs in order to keep itself in step. Everything here is specific to this store — the paths and ids are real, so the commands can be copied straight onto the server.',
'Shopify_G_Lead_Generic' => 'How a Shopify shop keeps itself in step with the ERP. Pick a store above to see its own state, or read it as it is — the cron line and the webhook URL are the same whichever store you connect.',
'Shopify_G_Ways_Note' => 'Most shops run both: the first keeps the shop current minute to minute, the second catches whatever the first missed — a webhook that never arrived, an edit made directly in the Shopify admin, a night when the site was down.',
'Shopify_G_Both_Need' => 'Both ways need this first',
'Shopify_G_Credentials' => 'Shopify credentials',
'Shopify_G_Cred_Intro' => 'Since January 2026 Shopify no longer creates custom apps inside the admin, so there are two kinds of connection:',
'Shopify_G_Cred_DevDash' => '{app} (any shop connected now) — {path}. Grant the Admin API scopes for what this store syncs, install the app on the shop, then copy the {clientId} and {clientSecret} from the app\'s Settings page into {where}. The ERP exchanges them for an access token itself and renews it before it expires every 24 hours. The client secret also signs webhooks, so nothing else is needed. The app and the shop must sit in the same Shopify organisation.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard app',
'Shopify_G_Cred_Legacy' => '{app} (created in the admin before 2026) — keeps working unchanged with its {token} ({prefix}) and its {secret} as the webhook signing secret. Not the same value as the token, and getting them the wrong way round is the usual reason webhooks are refused.',
'Shopify_G_Legacy_App' => 'Legacy custom app',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'stored',
'Shopify_G_Missing_Refused' => 'missing — deliveries will be refused',
'Shopify_G_Where_Data_Desc' => '{path} The ERP warehouse whose stock this shop sells, and the Shopify location that stock is written to. Inventory sync and order import both refuse to run without them.',
'Shopify_G_Currently' => 'Currently: warehouse {warehouse}, location {location}',
'Shopify_G_Not_Set_Lower' => 'not set',
'Shopify_G_Ready' => 'ready',
'Shopify_G_Incomplete' => 'incomplete',
'Shopify_G_Manual_Syncs' => 'Syncs you start by hand',
'Shopify_G_Manual_Desc' => 'A sync started from the {centre} answers at once and runs in the background, in short slices that each carry on from where the last one stopped. A big catalogue is never cut off part-way by hosting that ends long web requests (LiteSpeed, nginx, a load balancer), and closing the page does not stop it. The worker for that is one more cron line:',
'Shopify_G_Cron_Copied' => 'Cron line copied',
'Shopify_G_Manual_Note' => 'Without it a sync still finishes, but only while the Sync Centre page stays open: when no worker picks a run up within a few seconds, the page carries it on itself, one short request at a time. On Windows use Task Scheduler every minute: program {program}, arguments {args}, started in {dir}.',
'Shopify_G_Then_Pick' => 'Then pick how it keeps in step',
'Shopify_G_Right_Away' => 'Right away',
'Shopify_G_Stock_Live' => 'stock live',
'Shopify_G_Stock_Not_Live' => 'stock not live',
'Shopify_G_Realtime_Lead' => 'Each change is sent as it happens, in seconds. Two halves, and they are separate switches: {webhooks} bring the shop\'s own events in, and {push} sends stock out.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'instant stock push',
'Shopify_G_Webhooks_In' => 'Webhooks — the shop → the ERP',
'Shopify_G_Webhooks_Desc' => 'Orders, order status changes, and product, customer and stock edits made in Shopify. Open the store and press {button} on its {tab} — safe to press twice. Shopify posts to:',
'Shopify_G_Webhooks_Tab' => 'Webhooks tab',
'Shopify_G_Webhooks_Note' => 'The address must be reachable from the internet over HTTPS — Shopify will not deliver to {localhost} or a {test} domain. Each delivery is recorded once, so Shopify\'s retries cannot create a duplicate order, and a failed one can be replayed. Deliveries are refused until the signing secret from step 1 is stored.',
'Shopify_G_Instant_Out' => 'Instant stock push — the ERP → the shop',
'Shopify_G_Setting_Missed' => 'This is the setting people miss',
'Shopify_G_Pos_Not_Auto' => 'A POS sale does {not} reach Shopify by itself. Left off, the shop only finds out on the next Inventory push step — and in that window it can sell a unit you have already sold at the till.',
'Shopify_G_Not' => 'not',
'Shopify_G_Tick_Push' => 'Tick {setting} on {where}. That is the whole setup — no worker, no cron. Every sale, return and adjustment then sends a push of just those products, right after the sale is saved, and a twenty-line sale costs one push, not twenty. The till never waits for it.',
'Shopify_G_This_Store' => 'This store:',
'Shopify_G_Push_On' => 'on — stock pushed on change',
'Shopify_G_Push_Off' => 'off — stock on the schedule only',
'Shopify_G_Push_Note' => 'Only products that already have a Shopify mapping, and only movements in this store\'s warehouse, are pushed. Bulk operations — deleting a product, resetting a warehouse — write stock without firing an event, which is one reason to keep the scheduled inventory step as well.',
'Shopify_G_Nothing_Install' => 'Nothing else to install',
'Shopify_G_No_Worker_Note' => 'Neither half needs a queue worker or a cron entry. A webhook coming in is handled in the request Shopify makes; a stock push going out runs in the same process that served the sale, {after} the response has gone back — so the till is never waiting on Shopify, and a shop that stops answering is given up on after ten seconds and left to the next scheduled inventory push.',
'Shopify_G_After' => 'after',
'Shopify_G_Artisan_Note' => 'One exception: a stock change made by an artisan command has no response to come after, so it is queued on {queue} instead. If you want those to go out promptly too, drain that queue:',
'Shopify_G_On_Schedule' => 'On a schedule',
'Shopify_G_On_Lower' => 'on',
'Shopify_G_Off_Lower' => 'off',
'Shopify_G_Scheduled_Lead' => 'Everything is re-checked every so often, both ways. Slower than real time, but it is what pushes stock out on shops that do not use instant push, what catches a missed webhook, and the only way to move a whole catalogue.',
'Shopify_G_Cron_Entry' => 'The cron entry',
'Shopify_G_Cron_Entry_Desc' => 'Nothing scheduled runs without it. One line, this module only — add it next to whatever else you have chosen to schedule:',
'Shopify_G_Cron_Note' => 'Every five minutes is the finest resolution a plan can use, because five minutes is the shortest step interval. A coarser entry simply becomes the floor — with {example}, a step set to 5 minutes runs every 15. On Windows use Task Scheduler: program {program}, arguments {args}, started in {dir}.',
'Shopify_G_Switch_On_Plan' => 'Switch it on, and choose the plan',
'Shopify_G_Plan_Desc' => '{where} The switch decides whether cron may act at all; the plan decides what it does. A {step} is one entity in one direction with its own interval — {first}, {second}. The default interval is used by any step that leaves its own box empty.',
'Shopify_G_Step_Lower' => 'step',
'Shopify_G_Plan_Note' => 'Leave the plan empty and the store pulls orders and pushes stock at the default interval, which is what most shops want. Orders are pull-only: Shopify is where a customer places one.',
'Shopify_G_Schedule_On' => 'schedule on',
'Shopify_G_Schedule_Off' => 'schedule off — manual only',
'Shopify_G_When_Step_Runs' => 'When a step actually runs',
'Shopify_G_When_Note' => 'A step is due when that same step last {started} longer ago than its interval, read from the run history. So a sync you start by hand postpones the next automatic one, and a step that keeps failing is retried on its interval rather than every tick. The store\'s Overview shows each step\'s last run, next due time, and the reason it is blocked when it is. Run the first catalogue push by hand — with {dryRun} first — before putting it on a schedule.',
'Shopify_G_Started_Lower' => 'started',
'Shopify_G_Where_Setting' => 'Where each setting lives',
'Shopify_G_Where_Setting_Note' => 'All of these are on an existing store: {path}, then the pencil (or {edit} on the store\'s own page).',
'Shopify_G_Product_Images' => 'Product images',
'Shopify_G_Img_1' => 'Pictures go out with the product on a {push} — the main image first, then the gallery, then one per variant that has its own, up to fifty.',
'Shopify_G_Products_Push' => 'products push',
'Shopify_G_Img_2' => 'A variant\'s picture is uploaded with the product and then {assigned}, which is how Shopify models it: a variant points at one of the product\'s images. A variant reusing the main image does not upload it twice.',
'Shopify_G_Assigned' => 'assigned to that variant',
'Shopify_G_Img_3' => 'An image stored as a file is {uploaded} to Shopify, not linked, so it works even when this installation is not reachable from the internet. An image added as a pasted link is handed to Shopify as that URL, which must be publicly reachable.',
'Shopify_G_Uploaded' => 'uploaded',
'Shopify_G_Img_4' => 'They are only re-sent when they actually change — a push that only alters a price leaves the shop\'s images alone, because sending them replaces the whole set.',
'Shopify_G_Img_5' => 'Removing an image in the ERP does {not} delete it in Shopify. Delete it there too, or the shop keeps showing it.',
'Shopify_G_Commands' => 'Commands worth knowing',
'Shopify_G_Command_Copied' => 'Command copied',
'Shopify_G_Foot' => 'Every sync writes to {logs}, and each store\'s Overview shows when each step last ran, when it is next due, and what is blocking it when something is. That is where to look first when a sync did not do what you expected.',
'Shopify_G_Covers' => 'Covers',
'Shopify_G_Covers_Rt' => 'Orders and edits made in Shopify; stock leaving the ERP (a POS sale, a return, an adjustment)',
'Shopify_G_Covers_Sch' => 'Everything, both ways — including catalogue pushes and anything the fast path missed',
'Shopify_G_Speed' => 'Speed',
'Shopify_G_Speed_Rt' => 'Seconds',
'Shopify_G_Speed_Sch' => 'The step\'s interval (5 minutes to 7 days)',
'Shopify_G_Needs' => 'Needs',
'Shopify_G_Needs_Rt' => 'A public HTTPS address and the signing secret for incoming webhooks. Outgoing stock needs nothing at all',
'Shopify_G_Needs_Sch' => 'A cron entry running {cmd}',
'Shopify_G_Switched_On_At' => 'Switched on at',
'Shopify_G_On_Sch' => '{path}, plus the plan',
'Shopify_G_Scope_Orders' => '{scope} ({extra} for orders over 60 days old)',
'Shopify_G_Admin_Scopes' => 'Admin API scopes',
