'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash and SSLCommerz are used by the ONLINE STORE checkout only.',
'StoreAdm_PG_Intro_Desc' => 'Stripe keys are shared globally (admin and online store use the same Stripe integration). Each tab switches its method on or off for the online-store checkout; Offline Payments holds the methods paid outside the system.',
