'StoreAdm_PG_Paypal_Webhook_Hint' => 'Backstop for payments whose browser redirect never lands, plus refunds/chargebacks. Register a webhook on {site} pointing to the URL below (events: {events}) and paste its Webhook ID here.',
'StoreAdm_PG_Webhook_Url' => 'Webhook URL:',
