'StoreAdm_PG_Paypal_Disabled_Desc' => 'Turn PayPal on and enter your REST app Client ID and Secret (from {site}) to let customers pay with PayPal at the online-store checkout.',
'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
