'StoreAdm_PG_Paystack_Test_Live' => 'Test vs live is decided by the key pair: {test} keys run in test mode, {live} keys charge real cards — there is no separate sandbox switch.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook URL (optional backstop — set it under Settings → API Keys & Webhooks on the Paystack dashboard; requests are HMAC-verified with your secret key):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Turn Paystack on and enter your Public and Secret keys (from {site} → Settings → API Keys) to accept cards, bank transfers and mobile money at the online-store checkout.',
