'StoreAdm_PG_Flutterwave_Hash_Hint' => 'The Secret Hash you set under Settings → Webhooks on the Flutterwave dashboard; incoming webhooks are rejected unless their {header} header matches.',
'StoreAdm_PG_Flutterwave_Info' => 'Uses the Flutterwave v3 API with classic keys. Test vs live is decided by the key pair ({keys} vs live keys) — there is no separate sandbox switch. The store currency must be enabled on your Flutterwave account.',
