'Cr_Guide_Step_Account' => 'Add a courier account',
'Cr_Guide_Step_Account_Help' => 'Pick your courier and paste the API keys from its dashboard. Several accounts are fine, for example one per warehouse.',
'Cr_Guide_Step_Test' => 'Test the connection',
'Cr_Guide_Step_Test_Help' => 'Test connection checks the keys and often lists the codes the courier options ask for.',
'Cr_Guide_Step_Webhook' => 'Register the webhook URL',
'Cr_Guide_Step_Webhook_Help' => 'Couriers that push updates need the account webhook URL (listed below) so statuses change instantly. The others are checked on a schedule.',
'Cr_Guide_Step_Cod' => 'Choose where COD payouts go',
'Cr_Guide_Step_Cod_Help' => 'In Courier Settings, pick the account COD payouts are recorded into, and how returned parcels and courier charges are handled.',
