'Cr_Guide_Step_Book_Help' => 'On the sales list, open a sale menu and choose Send to courier, or tick several sales and send them at once.',
'Cr_Guide_Step_Errors' => 'Keep an eye on errors',
'Cr_Guide_Step_Errors_Help' => 'No courier errors in the last 24 hours.',
'Cr_Guide_Courier_Setup' => 'Courier setup',
'Cr_Guide_Pick_Courier' => 'Pick a courier to see what it needs',
