'Cr_Guide_How_It_Works' => 'How it works',
'Cr_Guide_Meaning' => 'Meaning',
'Cr_Guide_T_Statuses' => 'Statuses',
'Cr_Guide_Statuses_Note' => 'Statuses only move forward, so a late update never drags a parcel back. A delivered parcel can still be reported as returning or returned.',
'Cr_Guide_S_booked' => 'The courier has the order; nobody has collected it yet. A booking can be cancelled only now.',
'Cr_Guide_S_picked_up' => 'The courier collected the parcel.',
'Cr_Guide_S_in_transit' => 'Moving between hubs, in customs or held.',
'Cr_Guide_S_out_for_delivery' => 'With the rider today.',
'Cr_Guide_S_failed_attempt' => 'Not home, refused or wrong address. The courier tries again or returns it.',
'Cr_Guide_S_delivered' => 'Handed to the customer. A COD amount becomes collected by the courier.',
'Cr_Guide_S_returning' => 'On its way back to you.',
'Cr_Guide_S_returned' => 'Back with you: it waits in Returns to review, or is restocked automatically.',
'Cr_Guide_S_cancelled' => 'The booking was cancelled.',
'Cr_Guide_T_Booking' => 'Booking orders',
'Cr_Guide_B_Booking' => 'Send to courier fills the form from the sale: receiver, address, the amount still due as COD, and the weight of the products. Couriers with their own city lists show a picker, and your choice is remembered for that city. Aggregators, DHL, FedEx, UPS and Lalamove offer Compare rates: pick a price and Book buys it. Several sales can be booked at once from the sales list.',
'Cr_Guide_T_Cod' => 'Cash on delivery',
'Cr_Guide_B_Cod' => 'A COD parcel goes from Not collected to Collected by courier (on delivery) to Paid out to you. Couriers that report payouts move the last step themselves; for the others use Update COD. With an account chosen in Courier Settings, a payout is recorded as a payment on the sale. Courier charges can be saved as an expense once a parcel is finished.',
'Cr_Guide_T_Returns' => 'Returned parcels',
'Cr_Guide_B_Returns' => 'By default a returned parcel waits in Courier Shipments under Returns to review. Restock creates a sale return for the whole order and puts the items back in stock; Dismiss puts nothing back, for damaged or lost parcels. Courier Settings can restock automatically instead.',
'Cr_Guide_T_Customers' => 'Customer messages and tracking page',
'Cr_Guide_B_Customers' => 'Customer notifications in Courier Settings send SMS, email or WhatsApp at the statuses you tick, each once per parcel, with your own text. The tracking page in your online store lets customers follow a parcel by tracking number, or by order number and phone. Customers who often return parcels get a return-risk badge when you book.',
'Cr_Guide_T_Labels' => 'Labels',
'Cr_Guide_B_Labels' => 'Print label gives the courier\'s own label when it issues one (a PDF, a link or an image), otherwise a Stocky label with the tracking barcode and the amount to collect. Allow pop-ups for this site to print. DHL, FedEx and UPS give their label only once, at booking, and Stocky keeps it for reprints.',
'Cr_Guide_T_Faq' => 'Troubleshooting',
'Cr_Guide_Q_Test' => 'Test connection fails',
'Cr_Guide_A_Test' => 'Test-mode keys go with Test mode and live keys with Live; they are different. Open Courier logs and read the courier\'s answer for the exact reason.',
'Cr_Guide_Q_City' => 'The courier rejects the city or address',
'Cr_Guide_A_City' => 'Pick the city from the courier city list in the booking form; couriers only accept their own names. Couriers that work with postal addresses also need the state, postal code and two-letter country.',
'Cr_Guide_Q_Webhook' => 'Statuses do not change by themselves',
'Cr_Guide_A_Webhook' => 'For couriers that push, check the webhook URL is registered at the courier: Courier logs shows every update received, or why one was rejected (for example a wrong secret). Other couriers are checked on the schedule in Courier Settings, and Check status now asks at once.',
'Cr_Guide_Q_Stuck' => 'A shipment shows a status check error',
'Cr_Guide_A_Stuck' => 'The courier refused the last checks; the reason is on the shipment and in Courier logs. After repeated failures a shipment is no longer checked automatically: fix the cause, then use Check status now.',
'Cr_Guide_Q_Label' => 'Nothing opens when printing a label',
'Cr_Guide_A_Label' => 'Your browser blocked the pop-up. Allow pop-ups for this site and try again.',
'Cr_Guide_Q_Cod' => 'A COD payout was not recorded on the sale',
'Cr_Guide_A_Cod' => 'In Courier Settings, cash on delivery needs the switch on and an account chosen. Without an account, payouts are only marked as paid out.',
