'Tfa_Guide_App_Title' => 'Install an authenticator app',
'Tfa_Guide_App_Text' => 'Any app that supports standard 6-digit codes (TOTP) works. They are free and work offline:',
'Tfa_Guide_Enable_Title' => 'Turn it on from the profile',
'Tfa_Guide_Enable_1' => 'Open Profile (avatar menu at the top right) and find the "Two-factor authentication" card.',
'Tfa_Guide_Enable_2' => 'Click "Turn on" and confirm with the current password.',
'Tfa_Guide_Enable_3' => 'Scan the QR code with the app, or type the key shown under it.',
'Tfa_Guide_Enable_4' => 'Enter the 6-digit code the app shows to finish.',
'Tfa_Guide_Open_Profile' => 'Open my profile',
'Tfa_Guide_Codes_Title' => 'Save the recovery codes',
'Tfa_Guide_Codes_Text' => 'Right after setup, 8 recovery codes are shown once. Each one replaces a phone code a single time — for a lost, broken or reset phone. Download or copy them and keep them somewhere safe, away from the phone.',
'Tfa_Guide_Codes_Note' => 'Running low? "New recovery codes" on the profile replaces the whole set; the old ones stop working.',
'Tfa_Guide_Signin_Title' => 'Signing in',
'Tfa_Guide_Signin_Text' => 'After the email and password, the login page asks for the current code from the app. Codes change every 30 seconds and each one works once.',
'Tfa_Guide_Signin_Trust' => 'Ticking "Don’t ask again on this device" skips the code on that browser for :days days.',
'Tfa_Guide_Signin_Recovery' => 'No phone at hand? Click "Use a recovery code" and type one of the saved codes.',
'Tfa_Guide_Admin_Title' => 'For administrators',
'Tfa_Guide_Require_Title' => 'Make it mandatory',
'Tfa_Guide_Require_Text' => 'Turn on "Require two-factor authentication" on this card, then pick the roles that must use it — or leave the list empty for every user. Click Submit to save.',
'Tfa_Guide_Require_Next' => 'Nobody is signed out. Users who don’t have 2FA yet are walked through setup on the login page at their next sign-in, before they get in, and see their recovery codes there.',
'Tfa_Guide_Require_Note' => 'Users it is required for cannot turn it off from their profile.',
'Tfa_Guide_Trust_Title' => 'Trusted devices',
'Tfa_Guide_Trust_Text' => '"Remember trusted devices" sets how long a browser can skip the code after a successful sign-in. Choose "Always ask for a code" for shared or public computers such as a shop-floor POS.',
'Tfa_Guide_Trust_Note' => 'Lowering the number shortens devices already trusted; turning 2FA off or resetting it forgets them all.',
'Tfa_Guide_Lost_Title' => 'Lost phone and no recovery codes',
'Tfa_Guide_Lost_Text' => 'On the Users page, users with 2FA show "On" in the 2FA column. The shield button in Actions resets it: the user signs in with just the password and sets up the app again (or is asked to, if it is required).',
'Tfa_Guide_Lost_Warn' => 'Confirm who is asking before resetting — a reset removes the protection 2FA gives that account.',
'Tfa_Guide_Open_Users' => 'Open Users',
'Tfa_Guide_Mobile_Title' => 'Mobile app and API',
'Tfa_Guide_Mobile_Text' => 'The mobile app and the API token endpoint ask for the same code. If 2FA is required for a user who hasn’t set it up yet, they must sign in on the web once to do so.',
'Tfa_Guide_Protect_Title' => 'Built-in protection',
'Tfa_Guide_Protect_1' => '5 wrong codes block code entry for that user for 15 minutes, whatever the lockout settings above.',
'Tfa_Guide_Protect_2' => 'Each code and each recovery code works only once.',
'Tfa_Guide_Protect_3' => 'With "Record sign-in activity" on, wrong codes appear in the Sign-in activity list as "Wrong 2FA code".',
'Tfa_Guide_Trouble_Title' => 'Troubleshooting',
'Tfa_Guide_Faq_Clock_Q' => '“That code is not valid” with a fresh code',
'Tfa_Guide_Faq_Clock_A' => 'The phone clock is probably off. Codes depend on the time: set the phone’s date and time to automatic (network time), then try the next code.',
'Tfa_Guide_Faq_Phone_Q' => 'Moving to a new phone',
'Tfa_Guide_Faq_Phone_A' => 'Either use the authenticator app’s own transfer feature, or turn 2FA off on the profile and on again with the new phone (if it is required, ask an admin to reset it instead).',
'Tfa_Guide_Faq_Locked_Q' => '“Too many invalid codes”',
'Tfa_Guide_Faq_Locked_A' => 'Wait for the time shown (up to 15 minutes), or have an admin reset the user’s 2FA.',
'Tfa_Guide_Faq_Key_Q' => 'Nobody with 2FA can sign in after a server move',
'Tfa_Guide_Faq_Key_A' => 'The 2FA secrets are encrypted with the APP_KEY in the .env file. Keep the same APP_KEY when moving or restoring the app; if it changed, an admin without 2FA must reset the affected users.',
'Tfa_Guide_Button' => 'Guide',
