'Tfa_Guide_Rollout_Title' => 'Roll it out to every user',
'Tfa_Guide_Rollout_1' => 'Turn it on for your own account first (Profile), so you know the steps.',
'Tfa_Guide_Rollout_2' => 'Tell your team which app to install and that setup takes a minute at sign-in.',
'Tfa_Guide_Rollout_3' => 'Turn on "Require two-factor authentication", leave "Required for" empty (= every user), and optionally pick a grace period. Click Submit.',
'Tfa_Guide_Rollout_4' => 'Click "Sign out users without 2FA" so people already signed in set it up now instead of at some later sign-in. You stay signed in.',
'Tfa_Guide_Rollout_5' => 'Follow progress with the counter on this card, or the "Needs setup" filter on the Users page.',
'Tfa_Guide_Rollout_Note' => 'With a grace period, the setup screen shows “Remind me later” until the deadline; after it, setup is required to sign in.',
'Tfa_Guide_Customers_Title' => 'Customer accounts (store and client portal)',
'Tfa_Guide_Customers_Text' => 'Customers can protect their own accounts too. It is optional for each customer and never forced: switch it on under Store Settings → Registration Access Control (online store) and Client Portal → Portal Settings (client portal).',
'Tfa_Guide_Customers_1' => 'Customers turn it on from My Account (store) or Profile (portal).',
'Tfa_Guide_Customers_2' => 'They choose a code sent by email — easiest, no app needed — or an authenticator app with recovery codes.',
'Tfa_Guide_Customers_3' => 'Emailed codes need working mail settings (Settings → Mail Settings). They expire after 10 minutes.',
'Tfa_Guide_Customers_4' => 'Switching the option off later stops new setups; customers who already use it keep being asked and can turn it off themselves.',
