'Woo_Log_Abort_Title' => 'Sync stopped after repeated failures',
'Woo_Log_Abort_Explain' => 'WooCommerce refused {count} products in a row, so the sync stopped instead of trying the rest. Nothing was lost — products that synced before this point are saved.',
'Woo_Log_Abort_Fix' => "Fix the problem described above.\nRun the product sync again — it carries on from where it stopped.",
'Woo_Log_Gtin_Title' => 'Barcode already used or not valid',
'Woo_Log_Gtin_Explain' => 'WooCommerce refused this product’s barcode (GTIN / UPC / EAN / ISBN). In WooCommerce a barcode can belong to only one product or variation in the whole shop, and it may contain only digits and hyphens. Products in the WooCommerce trash still keep their barcode.',
'Woo_Log_Gtin_Fix' => "Open the WooCommerce product shown below as already using it. If it is an old copy or in the trash, delete it permanently; otherwise remove its barcode.\nIf several Stocky products share this barcode, give each one its own barcode (or leave it empty).\nIf the barcode has spaces or letters, correct it in Stocky.\nRun the sync again.",
'Woo_Log_Sku_Title' => 'SKU already used in WooCommerce',
'Woo_Log_Sku_Explain' => 'Another WooCommerce product already has this SKU, so WooCommerce will not create a second one. This is often an old product sitting in the WooCommerce trash.',
'Woo_Log_Sku_Fix' => "In WooCommerce, look for a product with this SKU — check Products → Trash too.\nRestore it if it is the same product, or delete it permanently if it is not needed.\nRun the sync again.",
'Woo_Log_MissingSku_Title' => 'Product has no SKU',
'Woo_Log_MissingSku_Explain' => 'Stocky matches products with WooCommerce by their code (SKU). This product has none, so it was skipped.',
'Woo_Log_MissingSku_Fix' => "Edit the product in Stocky and give it a code.\nRun the sync again.",
