'Woo_Log_Category_Fix' => "Sync categories first.\nThen run the product sync again.",
'Woo_Log_Brand_Title' => 'Brand not in WooCommerce yet',
'Woo_Log_Brand_Explain' => 'This product’s brand has not been sent to WooCommerce, so the product was synced without it.',
'Woo_Log_Brand_Fix' => "Sync brands first.\nThen run the product sync again.",
'Woo_Log_Ambiguous_Title' => 'Could not confirm the matching WooCommerce product',
